import Fuse from "fuse.js";
import type { SkyObject } from "@/lib/astro/types";
import { normalizeQuery, parseCatalogId } from "./normalize";

export interface SearchIndex {
  search: (query: string, limit?: number) => SkyObject[];
}

/**
 * Resolution order (see docs/06-search-spec.md):
 *  1. exact normalized alias hit
 *  2. catalog-id parse (HIP/HD/HR/GJ/M/NGC/IC) -> cross-reference table
 *  3. prefix match on aliases
 *  4. fuzzy (Fuse) fallback for typos
 * TODO(agent): load aliases.json generated by scripts/build-catalog.mjs instead of building from `objects` only.
 */
export function buildSearchIndex(objects: SkyObject[]): SearchIndex {
  const aliasMap = new Map<string, SkyObject>();
  for (const o of objects) {
    for (const name of [o.name, ...(o.designations ?? [])]) aliasMap.set(normalizeQuery(name), o);
  }
  const fuse = new Fuse(objects, { keys: ["name", "designations"], threshold: 0.35 });

  return {
    search(query, limit = 8) {
      const q = query.trim();
      if (!q) return [];
      const out: SkyObject[] = [];
      const seen = new Set<string>();
      const add = (o?: SkyObject) => {
        if (o && !seen.has(o.id)) { seen.add(o.id); out.push(o); }
      };

      const norm = normalizeQuery(q);
      add(aliasMap.get(norm));

      const cat = parseCatalogId(q);
      if (cat) {
        // TODO(agent): resolve via xref table, e.g. M31 <-> NGC 224 <-> "Andromeda Galaxy"
      }

      for (const [key, o] of aliasMap) if (key.startsWith(norm)) add(o);
      for (const r of fuse.search(q, { limit })) add(r.item);
      return out.slice(0, limit);
    },
  };
}
